// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameters: newOwner is the address we ask setOwner to set; caller is the address that invokes setOwner.
    // General rule: if caller is the current owner, then after calling setOwner(newOwner) the contract's owner() equals newOwner.
    // The mutant that assigns owner = msg.sender will break this when newOwner != caller.
    function testFuzz_property(address caller, address newOwner) public {
        // keep domain wide but ensure caller is not zero address (legitimate actor)
        vm.assume(caller != address(0));
        // ensure newOwner is not zero to avoid trivialities
        vm.assume(newOwner != address(0));

        // The contract's deployer (this test) is the initial owner (set in setUp via new C()).
        address deployer = address(this);

        // First, set the owner to `caller` by calling setOwner as deployer (the current owner)
        // deployer is the test contract (address(this)), which is owner after deployment.
        bool ok;
        // call setOwner to assign ownership to caller
        try c.setOwner(caller) {
            ok = true;
        } catch {
            ok = false;
        }
        // This should succeed on the reference implementation for any caller (deployer is owner)
        vm.assume(ok);

        // Now, as the new owner (caller), call setOwner(newOwner).
        // We need the fuzzer to find a case that distinguishes behavior: when newOwner != caller,
        // reference will make c.owner() == newOwner, mutant will leave owner == caller.
        vm.prank(caller);
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }
        // require the call succeeded (on reference it should succeed because caller is owner)
        vm.assume(ok);

        // Single assertion: after caller (the current owner) calls setOwner(newOwner), c.owner() equals newOwner.
        assertTrue(c.owner() == newOwner);
    }
}

