contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address newOwner) public {
        // keep fuzz domain wide but exclude zero address? We allow zero as admissible too.
        // The property: when the caller is the current owner, setOwner(newOwner) results in owner == newOwner.
        // Ensure the caller is the current owner (deployer in setUp). vm.prank with the deployer (address of this test contract is not the deployer).
        // The deployer of C was this test contract when setUp ran (since setUp executed new C()).
        address deployer = address(this);

        // Sanity: ensure the fuzzer-supplied address is any address (including zero) - no assumption needed.
