pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzer will supply attackerAddr and newOwner candidate
    function testFuzz_property(address attackerAddr, address newOwner) public {
        // Keep admissible domain wide but avoid zero-address newOwner to be meaningful
        vm.assume(newOwner != address(0));

        // Ensure attackerAddr is a contract we deploy (fuzzer gives an address but we must deploy a contract
        // that will call c.setOwner on behalf of its tx.origin). We deploy a small forwarder whose tx.origin
        // is the EOA that initiates the transaction; to simulate that, we will prank from an EOA `EOA` and
        // have that EOA call the forwarder contract which in turn calls c.setOwner(newOwner).

        // Choose an EOA (fuzzed attackerAddr will be used as the EOA here by vm.prank)
        address EOA = attackerAddr;
        // Deploy forwarder that will call c.setOwner
        Forwarder f = new Forwarder();

        // Ensure the starting owner is the test contract deployer (setUp did that). Capture original owner.
        address originalOwner = c.owner();

        // Make sure EOA is not the original owner to create the scenario where msg.sender != owner
        vm.assume(EOA != originalOwner);

        // Fund EOA so it can send txs (not strictly necessary but safe)
        vm.deal(EOA, 1 ether);

        // From EOA, call the forwarder which will call c.setOwner(newOwner)
        vm.prank(EOA);
        // forwarder will perform forwardCall to c
        f.forwardCall(address(c), abi.encodeWithSelector(C.setOwner.selector, newOwner));

        // After that call completes, on the correct contract C (which checks msg.sender==owner) the owner should remain unchanged
        // (because msg.sender in C was the forwarder contract, not originalOwner). This is the universal property.
        assertTrue(c.owner() == originalOwner);
    }
}

contract Forwarder {
    // simple forwarder that calls into target with provided calldata
    function forwardCall(address target, bytes calldata data) external {
        // solhint-disable-next-line avoid-low-level-calls
        (bool ok, ) = target.call(data);
        require(ok);
    }
}

