pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: attacker (immediate caller contract) and originOwner (EOA that is the original owner)
    function testFuzz_property(address attackerAddr, address originOwner) public {
        // keep addresses non-zero and distinct where meaningful
        vm.assume(attackerAddr != address(0));
        vm.assume(originOwner != address(0));

        // Deploy a helper contract at a deterministic address by using create2 via factory pattern isn't allowed here,
        // but we can simply deploy an Attacker helper and ignore attackerAddr for its creation; still fuzz attackerAddr
        // to satisfy requirement that some fuzz parameters exist. We will use originOwner as the EOA that will be owner.

        // Ensure originOwner is funded so it can be tx.origin and perform calls
        vm.deal(originOwner, 1 ether);

        // Make originOwner the owner by having it call setOwner(originOwner) as itself (it is owner by constructor, but constructor set deployer as owner; our test deployer is this test contract, not originOwner)
        // To set owner to originOwner on the reference contract, current owner is test contract (deployer of c). We must call from that owner.
        // c was deployed in setUp() with owner = address(this). So current owner is address(this).
        // Call setOwner as address(this) to set owner = originOwner
        bool ok;
        try c.setOwner(originOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        // this should succeed on the reference contract
        assertTrue(ok);
        // Now owner == originOwner
        assertTrue(c.owner() == originOwner);

        // Deploy a forwarding contract that, when called, will call c.setOwner(attackerAddr)
        Forwarder f = new Forwarder(c);

        // Now simulate originOwner externally calling the forwarder (so tx.origin == originOwner, msg.sender == address(f))
        vm.startPrank(originOwner);
        // forwarder will call setOwner with attackerAddr as the desired new owner
        try f.execSetOwner(attackerAddr) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // GENERAL ASSERTION: On the correct contract C, only the immediate caller equal to owner (msg.sender == owner)
        // can change owner; since the immediate caller here is the Forwarder (not originOwner), the reference will NOT
        // allow this change and owner should remain originOwner for ALL admissible inputs. The mutant using tx.origin
        // will accept because tx.origin == originOwner and will set owner to attackerAddr for some inputs; thus this
        // single assertion distinguishes them.
        assertTrue(c.owner() == originOwner);
    }
}

contract Forwarder {
    C immutable c;
    constructor(C _c) { c = _c; }
    function execSetOwner(address _new) external {
        // call c.setOwner(_new) as this contract (msg.sender == address(this), tx.origin preserved)
        c.setOwner(_new);
    }
}

