        // Expected owner after the call according to correct contract:
        address expectedOwner;
        if (actor == currentOwner) {
            // owner can change to actor (idempotent), and call should succeed
            expectedOwner = actor;
        } else {
            // non-owners cannot change owner; owner must remain currentOwner
            expectedOwner = currentOwner;
        }

        // Single assertion reading c's public getter
        assertTrue(c.owner() == expectedOwner);
    }
